import { NATIVE_CAPABILITIES } from "../../core/engine.js";
import type { EngineContext, PlayerEngine } from "../../core/engine.js";
import { createPlayerError } from "../../core/errors.js";
import {
  bindMediaElement,
  bufferedEnd,
  safeDuration,
  waitForMetadata,
} from "../../core/media-events.js";
import type { AudioTrackInfo, CaptionTrack, TextTrackInfo } from "../../core/types.js";
import { clamp } from "../../core/utils.js";
import { createMediaElement, removeElement } from "../shared/dom.js";
import {
  applyCaptionTracks,
  listAudioTracks,
  listTextTracks,
  setMediaAudioTrack,
  setMediaTextTrack,
} from "../shared/media-tracks.js";

function sourceCaptions(context: EngineContext): readonly CaptionTrack[] | undefined {
  const fromOptions = context.options.captions?.tracks;
  const fromSource = context.source.source.captions;

  if (fromOptions !== undefined && fromOptions.length > 0) {
    return fromOptions;
  }

  return fromSource;
}

function preferredCaptionId(context: EngineContext): string | null {
  const configured = context.options.captions?.defaultTrack;

  if (configured !== undefined) {
    return configured;
  }

  const tracks = sourceCaptions(context) ?? [];
  return tracks.find((track) => track.default === true)?.id ?? null;
}

/** Native `<video>`/`<audio>` engine. */
export function createNativeEngine(context: EngineContext): PlayerEngine {
  const { source, options, emit } = context;
  let media: HTMLVideoElement | HTMLAudioElement | null = null;
  let detach: (() => void) | null = null;

  return {
    kind: source.kind,
    get element() {
      return media;
    },
    capabilities: NATIVE_CAPABILITIES,

    async load(): Promise<void> {
      const element =
        source.kind === "audio"
          ? createMediaElement("audio", options)
          : createMediaElement("video", options);
      media = element;
      detach = bindMediaElement(element, emit);
      applyCaptionTracks(element, sourceCaptions(context));
      context.host.append(element);

      if (source.stream !== null) {
        element.srcObject = source.stream;
      } else {
        element.src = source.url;
      }

      const metadata = waitForMetadata(element);
      element.load();
      await metadata;

      const preferred = preferredCaptionId(context);

      if (options.captions?.enabled === false) {
        setMediaTextTrack(element, null);
      } else if (preferred !== null) {
        setMediaTextTrack(element, preferred);
      }
    },

    async play(): Promise<void> {
      if (media === null) {
        throw createPlayerError("No media element is attached.", { code: "invalid-state" });
      }

      await media.play();
    },

    pause(): void {
      media?.pause();
    },

    seek(time: number): void {
      if (media === null) {
        return;
      }

      const duration = safeDuration(media);
      media.currentTime = duration > 0 ? clamp(time, 0, duration) : Math.max(0, time);
    },

    setVolume(volume: number): void {
      if (media !== null) {
        media.volume = clamp(volume, 0, 1);
      }
    },

    setMuted(muted: boolean): void {
      if (media !== null) {
        media.muted = muted;
      }
    },

    setPlaybackRate(rate: number): void {
      if (media !== null) {
        media.playbackRate = clamp(rate, 0.25, 4);
      }
    },

    setTextTrack(id: string | null): void {
      if (media !== null) {
        setMediaTextTrack(media, id);
      }
    },

    setAudioTrack(id: string | null): void {
      if (media !== null) {
        setMediaAudioTrack(media, id);
      }
    },

    getQualities(): readonly [] {
      return [];
    },

    getTextTracks(): readonly TextTrackInfo[] {
      return media === null ? [] : listTextTracks(media);
    },

    getAudioTracks(): readonly AudioTrackInfo[] {
      return media === null ? [] : listAudioTracks(media);
    },

    getCurrentTime(): number {
      return media?.currentTime ?? 0;
    },

    getDuration(): number {
      return media === null ? 0 : safeDuration(media);
    },

    getBuffered(): number {
      return media === null ? 0 : bufferedEnd(media);
    },

    destroy(): void {
      detach?.();
      detach = null;

      if (media !== null) {
        media.pause();
        media.removeAttribute("src");
        media.srcObject = null;
        media.load();
        removeElement(media);
        media = null;
      }
    },
  };
}
